          "신명기는 민수기가 멈춘 자리에서 이어집니다. 민수기 36장 13절이 모압 평지 요단 가를 가리키며 끝났고, 신명기 1장 1~5절도 요단 저편 모압 땅에서 모세가 온 이스라엘에게 말한다고 시작합니다. 때는 시혼과 옥을 친 뒤이고(1:4), 모세는 이 율법을 풀어 설명하기 시작합니다(1:5). 책의 큰 부분은 새 사건이 아니라 모세가 하는 말입니다. 그는 먼저 호렙에서 떠나라는 말씀을 들은 날로 돌아갑니다(1:6~8). 그때 모세는 나 혼자서는 너희를 질 수 없다고 말했고, 백성이 좋다고 하자 지혜롭고 이름이 알려진 사람들을 세워 천 명, 백 명, 오십 명, 열 명 단위로 맡겼습니다(1:9~15). 재판관들에게는 작은 사람이나 큰 사람이나 똑같이 듣고 사람의 얼굴을 두려워하지 말라고 하며, 재판은 하나님께 속한 일이라고 합니다(1:16~17). 비슷한 말이 민수기 11장 14절에도 나옵니다.",
          "모세는 가데스바네아의 일도 되짚습니다. 이 책에서는 백성이 먼저 사람을 보내 땅을 살피자고 청했고 모세가 그 말을 좋게 여겼다고 적습니다(1:22~23). 민수기 13장 1~2절은 하나님의 말씀으로 시작합니다. 두 기록이 어떻게 이어지는지는 교회마다 이해가 다릅니다. 정탐꾼은 땅이 좋다고 보고했지만 백성은 올라가지 않았고, 천막에서 하나님이 우리를 미워하신다고 말했습니다(1:25~27). 모세는 두려워하지 말라고, 하나님이 이집트에서처럼 앞서 싸우신다고 했습니다(1:29~30). 그리고 광야에서 사람이 자기 아이를 들고 가듯 하나님이 그들을 길 내내 들고 오셨다고 합니다(1:31). 하나님은 그 세대 사람들 가운데 갈렙 말고는 그 땅을 보지 못하리라고 맹세하셨고(1:34~36), 어린아이들은 들어가리라고 하셨습니다(1:39). 올라가지 말라는 말씀을 듣지 않고 올라간 사람들은 패했습니다(1:41~44).",
          "모세는 자기 이야기도 그 안에 넣습니다. 너희 때문에 하나님이 내게도 노하셨다고 말하고(1:37), 3장에서는 하나님께 요단을 건너 그 좋은 땅을 보게 해 달라고 구했다고 합니다(3:23~25). 하나님은 그만하면 되었으니 이 일로 더 말하지 말라고 하시고, 비스가 꼭대기에서 눈으로 보라고 하시며, 여호수아를 세워 격려하라고 하십니다(3:26~28). 민수기 20장 12절에서 하나님은 모세와 아론이 나를 믿지 않았다고 말씀하셨고, 여기서 모세는 너희 때문이라고 되짚습니다(3:26; 4:21). 두 말이 어떻게 이어지는지는 교회마다 이해가 다릅니다. 본문은 그 이상을 설명하지 않습니다. 2장은 가데스바네아에서 떠난 지 서른여덟 해가 지났다고 적고(2:14), 사십 년 동안 하나님이 함께하셔서 부족한 것이 없었다고 말합니다(2:7). 에돔과 모압과 암몬 땅은 하나님이 따로 주신 땅이어서 건드리지 말라고 하셨습니다(2:5; 2:9; 2:19). 시혼의 성읍에서는 그 안의 사람들을 모두 진멸했다고 적습니다(2:34). 읽기 어려운 대목입니다. 정복에 관한 명령은 7장과 20장에서 다시 만나며, 오늘 어떻게 읽을지는 교회마다 이해가 다릅니다.",
          "4장에서 모세는 이제 규례를 들으라고 권합니다. 그 규례는 백성이 살고 그 땅에 들어가 차지하게 하려는 것입니다(4:1). 더하거나 빼지 말라고 하고(4:2), 이 규례를 지키는 것이 다른 나라들 앞에서 지혜가 된다고 합니다(4:6). 호렙에서 하나님은 불 가운데서 말씀하셨습니다. 백성은 말씀의 소리를 들었지만 형상은 보지 못했고, 소리만 들었습니다(4:12). 그래서 어떤 모양으로도 형상을 만들지 말라고 합니다(4:15~19). 하나님은 불에 견주어 말해지고 질투하시는 하나님으로 불리십니다(4:24). 그런 하나님이 흩어진 곳에서라도 마음을 다해 찾는 사람을 만나 주신다고 하고(4:29), 자비로운 하나님이어서 언약을 잊지 않으신다고 합니다(4:30~31). 이 장 끝쪽에는 요단 동쪽에 세 도피성을 구별했다는 말이 나옵니다(4:41~43)."
