        "look": "6장 4~5절에서 이스라엘이 듣는 것은 무엇이고, 어떻게 하라고 합니까? 6장 6~9절에서 이 말씀을 어디에 두라고 합니까? 6장 20~25절에서 아이가 물으면 어떤 이야기로 대답을 시작합니까? 7장 6~8절에서 하나님이 이스라엘을 택하신 까닭은 무엇이라고 합니까? 7장 17~19절에서 그 땅의 민족들이 자기보다 많다고 생각하는 마음에 무엇을 기억하라고 합니까?",
        "ask": "내가 매일 지나는 자리에서 하나님을 떠올리게 해 주는 것은 무엇입니까? 아이이든 어른이든 누군가가 왜 이렇게 사느냐고 묻는다면 어떤 이야기로 대답을 시작하겠습니까?",
        "p": [
          "6장은 이 말씀이 무엇을 위한 것인지로 시작합니다. 그 땅에 들어가 행하도록, 그리고 너와 아들과 손자가 하나님을 두려워하며 규례를 지키도록 가르치라는 것입니다(6:1~2). 이어서 이스라엘에게 들으라고 하는 두 줄이 나옵니다. 하나는 하나님에 관한 말이고, 하나는 사람에 관한 말입니다. 주님이 우리 하나님이시고 주님은 한 분이시라는 것(6:4), 그리고 마음과 목숨과 힘을 다해 하나님을 사랑하라는 것입니다(6:5). 첫 줄을 어떻게 옮길지는 번역마다 다릅니다. 주님이 우리 하나님, 주님은 한 분이라고 옮기기도 하고, 우리 하나님 주님은 오직 한 분이시라고 옮기기도 합니다. 둘 다 같은 히브리어 낱말 순서에서 나옵니다. 신약은 이렇게 잇습니다. 예수님은 가장 큰 계명이 무엇이냐는 물음에 이 두 줄을 들어 대답하십니다(막 12:29~30).",
          "이 말씀은 마음에 두고(6:6), 자녀에게 거듭 일러 주고, 집에 앉아 있을 때와 길을 걸을 때와 누울 때와 일어날 때 이야기하라고 합니다(6:7). 손에 매어 표로 삼고 이마 사이에 붙이며 문설주와 바깥문에 쓰라고도 합니다(6:8~9). 이 말을 글자 그대로 몸에 매고 문에 쓰는 일로 이어 온 사람들도 있고, 마음에 새기라는 뜻으로 읽는 사람들도 있습니다. 이 말씀을 오늘 어떻게 이을지는 교회마다 이해가 다릅니다. 10~12절에서 모세는 지은 적 없는 성읍과 채우지 않은 집을 받고 배부르게 될 때를 말하며, 그때 이집트에서 종살이하던 곳에서 데리고 나오신 분을 잊지 않도록 삼가라고 합니다. 아이가 이 규례가 무엇이냐고 물을 때의 대답은 규례를 설명하는 말이 아니라 이야기로 시작합니다. 우리는 이집트에서 바로의 종이었는데 하나님이 능한 손으로 데리고 나오셨다는 이야기입니다(6:20~23). 본문은 이 규례를 지키는 일이 하나님 앞에서 우리의 의로움이 될 것이라고 맺습니다(6:25). 이 말을 어떻게 이해할지는 교회마다 이해가 다릅니다.",
          "7장은 그 땅에 들어가 하나님이 많은 민족을 쫓아내실 때의 일을 말합니다(7:1). 본문은 그들을 진멸하고, 그들과 언약을 맺지 말고, 불쌍히 여기지 말고, 혼인하지 말라고 합니다(7:2~3). 이유는 그들이 이스라엘의 자녀를 하나님에게서 돌려세워 다른 신을 섬기게 할 것이기 때문이라고 합니다(7:4). 그들의 제단과 형상은 헐고 불살라야 합니다(7:5). 읽기 어려운 대목입니다. 본문은 이 명령을 그 땅에 들어가려는 이스라엘 앞에서 한 말로 적습니다(7:1). 이 정복 명령을 오늘 어떻게 읽을지는 교회마다 이해가 다릅니다. 20장 10~18절에서 전쟁에 관한 규정과 함께 다시 만납니다.",
          "같은 장에서 하나님이 이스라엘을 택하신 까닭도 말합니다. 이스라엘은 하나님께 속한 거룩한 백성이고(7:6), 하나님이 이스라엘을 택하신 것은 수가 많아서가 아니었고, 모든 민족 가운데 가장 적은 편이었다고 합니다. 까닭은 하나님이 이스라엘을 사랑하셨고 조상들에게 하신 맹세를 지키시려는 것이라고 합니다(7:7~8). 자기보다 많은 민족을 어떻게 쫓아내느냐고 마음속으로 말하게 되면, 두려워하지 말고 하나님이 이집트에서 하신 일을 기억하라고 합니다(7:17~19). 하나님이 그들을 조금씩 쫓아내실 것이라고도 합니다(7:22). 7장 9절은 하나님이 신실하셔서 사랑하고 계명을 지키는 사람에게 천 대까지 언약을 지키신다고 하고, 12~15절은 이 규례를 듣고 지키면 하나님이 언약을 지키시고 복을 주셔서 번성하게 하시며 질병을 멀리하시리라고 합니다. 이 약속은 그 땅으로 들어가는 이스라엘에게 한 언약 안의 말씀입니다. 오늘 이것을 어떻게 이을지는 교회마다 이해가 다릅니다. 이 말씀으로 오늘 누군가의 병이나 아이 없음의 까닭을 그 사람의 순종과 이어 읽는 것은 조심해야 합니다."
        ],
