        "look": "12장 5~7절에서 이스라엘이 하나님이 택하실 곳에서 하는 일은 무엇입니까? 13장 1~5절에서 이스라엘은 어떤 말에 귀를 기울이지 말라고 하고, 하나님은 그 일을 무엇이라 하십니까? 14장 22~29절에서 십분의 일은 해마다와 삼 년째에 각각 어떻게 쓰입니까? 15장 7~11절에서 가난한 이웃에게 어떻게 하라고 합니까? 15장 12~15절에서 종을 풀어 줄 때 어떻게 하라고 하고, 15절은 무엇을 기억하라고 합니까? 16장 11절과 14절에서 절기에 함께 기뻐하는 사람들은 누구입니까?",
        "ask": "내 손에 쥐고 있는 것 가운데 누군가와 나누어 먹고 싶은 것이 있습니까? 그 앞에서 내 마음은 어떻습니까?",
        "p": [
          "12장은 이 규례를 그 땅에서 지킬 규례라고 하면서 시작합니다(12:1). 먼저 그 땅의 민족들이 신을 섬기던 곳을 모두 허물고 제단과 기둥을 부수라고 합니다(12:2~3). 그 땅 민족들이 자기 신을 섬기던 식으로 하나님께 하지 말라고 합니다(12:4). 대신 하나님이 모든 지파 가운데서 택하여 이름을 두실 곳으로 가서 번제와 제사와 십분의 일과 서원 예물을 드리라고 합니다(12:5~6). 본문은 그곳의 이름을 적지 않습니다. 그곳에서 이스라엘은 가족과 함께 하나님 앞에서 먹고 기뻐합니다(12:7). 아들과 딸과 종과 여종, 그리고 함께 받을 몫이 없는 레위인도 함께 기뻐합니다(12:12). 이 장에는 그 땅의 민족들이 자기 신에게 자녀를 불에 드렸다는 말도 있고, 이스라엘은 그렇게 하지 말라고 합니다(12:31).",
          "13장은 읽기 어려운 대목입니다. 하나님이 아닌 다른 신을 따르자고 이끄는 말을 세 경우로 나누어 적습니다. 첫째는 표적을 보이는 예언자나 꿈꾸는 사람입니다. 그 말이 이루어져도 귀를 기울이지 말라고 하고, 그 일은 이스라엘이 하나님을 마음을 다해 사랑하는지 하나님이 시험하시는 것이라고 합니다(13:1~3). 이런 사람에게는 죽음의 벌을 정합니다(13:5). 둘째는 가까운 가족이나 친구가 몰래 이끄는 경우이고, 이때도 죽음의 벌을 정합니다(13:6~10). 셋째는 한 성읍의 사람들이 이끌려 가는 경우로, 소문을 들으면 먼저 자세히 조사하여 사실인지 살피라고 하고(13:12~14), 사실이면 그 성읍과 안의 모든 것을 진멸하라고 합니다(13:15~17). 이 형벌과 진멸 규정을 오늘 어떻게 이해할지는 교회마다 이해가 다릅니다.",
          "14장은 하나님의 거룩한 백성이라는 말로 시작합니다(14:2). 이어서 먹을 수 있는 동물과 먹지 못하는 동물을 나누는 규정이 나오는데, 레위기 11장과 비슷한 목록입니다(14:3~21). 본문은 오늘의 적용까지 말하지 않습니다. 22~29절은 십분의 일을 말합니다. 해마다 땅에서 난 것의 십분의 일을 하나님이 택하실 곳에서 하나님 앞에서 먹으라고 하고(14:22~23), 길이 멀면 돈으로 바꾸어 가서 마음에 원하는 먹을 것과 마실 것에 쓰고 가족과 함께 하나님 앞에서 먹고 기뻐하라고 합니다(14:24~26). 레위인을 저버리지 말라고 하고(14:27), 삼 년째 끝에는 그해의 십분의 일을 성읍에 쌓아 두어 레위인과 나그네와 고아와 과부가 와서 먹고 배부르게 하라고 합니다(14:28~29). 민수기 18장 21절은 십분의 일을 레위인의 기업으로 적습니다. 두 규정이 어떻게 이어지는지는 교회마다 이해가 다릅니다. 이 규정을 오늘의 헌금과 어떻게 이을지도 교회마다 이해가 다릅니다.",
          "15장은 일곱째 해의 면제를 말합니다. 이웃에게 꾸어 준 사람은 그것을 갚으라고 독촉하지 말고 놓아 주라고 합니다(15:1~2). 외국 사람에게서는 거두어도 된다고 적습니다(15:3). 4절은 번역마다 가난한 사람이 없게 될 것이라고도, 다르게도 옮기는 문장이고, 5절은 하나님의 말씀을 잘 듣고 지킬 때라고 조건을 붙입니다. 그런데 11절은 가난한 사람이 땅에서 그치지 않을 것이므로 손을 펴라고 합니다. 7~10절은 가난한 이웃에게 마음을 단단히 하지 말고 손을 움켜쥐지 말며 필요한 만큼 꾸어 주라고 합니다. 일곱째 해가 가까웠다고 악한 마음을 품고 주지 않으면 그 사람이 하나님께 부르짖어 죄가 된다고 합니다(15:9). 이 약속과 명령을 오늘 어떻게 이을지는 교회마다 이해가 다릅니다.",
          "15장 12~18절은 히브리 남자나 여자가 팔려 육 년을 섬기면 일곱째 해에 자유롭게 보내라고 하고, 빈손으로 보내지 말고 양 떼와 타작마당과 포도주 틀에서 넉넉히 주라고 합니다(15:12~14). 이집트에서 종이었음을 기억하라는 말이 이유로 붙습니다(15:15). 종이 스스로 남겠다고 하면 귀를 문에 대고 뚫어 영원히 종으로 둔다고 적습니다(15:16~17). 출애굽기 21장 2~7절은 딸을 종으로 판 경우는 남자 종처럼 풀려나지 않는다고 적습니다. 신명기 15장 12절은 남자와 여자를 함께 적습니다. 두 규정이 어떻게 이어지는지는 교회마다 이해가 다릅니다. 이 규정은 사람을 종으로 두는 일을 전제로 합니다. 읽기 어려운 대목이며 오늘 어떻게 이해할지는 교회마다 이해가 다릅니다.",
          "16장은 유월절과 칠칠절과 초막절을 말합니다(16:1~15). 칠칠절과 초막절에는 아들과 딸과 종과 여종, 레위인과 나그네와 고아와 과부가 함께 기뻐한다고 적습니다(16:11; 16:14). 모든 남자가 해마다 세 번 하나님이 택하실 곳에 나아오되 빈손으로 오지 말고 하나님이 주신 복에 따라 형편대로 드리라고 합니다(16:16~17). 18~20절은 재판관과 관리를 세우고, 사람의 얼굴을 보지 말고 선물을 받지 말며 정의를 따르라고 합니다. 한 장 안에서 절기의 기쁨과 재판의 정의가 이웃하여 놓입니다."
        ],
