        "read": "성경을 펴서 두 번 읽으며 모세가 여호수아와 백성에게 하는 말, 이 율법을 언제 누구 앞에서 읽게 하는지, 하나님이 모세에게 쓰라고 하신 노래가 하나님을 무엇에 견주는지, 모세가 마지막에 본 것과 그 뒤에 적힌 일을 살펴보십시오. 32장 노래는 길고 읽기 어려운 대목이 있습니다. 길게 느껴지면 31장 1~8절, 32장 1~14절, 32장 44~52절, 34장 1~12절을 먼저 읽어도 좋습니다.",
