          "모세가 언약의 책을 읽어 주자 백성은 이번에는 행하고 듣겠다고 대답합니다(24:7). 모세는 피를 백성에게 뿌리며 이것이 하나님이 이 모든 말씀대로 너희와 세우신 언약의 피라고 말합니다(24:8). 19장에서 시작된 약속이 책과 대답과 피로 매듭지어집니다. 같은 백성이 같은 날 두 번 대답하고, 두 번째 대답에는 듣는다는 말이 더해집니다. 이 대답이 얼마나 오래 가는지는 32장에서 드러납니다.",
          "모세와 아론과 나답과 아비후와 장로 일흔 명이 산에 올라가 이스라엘의 하나님을 봅니다. 하나님의 발 아래에는 청옥을 깐 듯하고 하늘처럼 맑은 것이 있었다고 적습니다(24:9~10). 하나님은 그들에게 손을 대어 해치지 않으셨고, 그들은 하나님을 뵌 채 먹고 마십니다(24:11). 거룩한 분 앞에 가까이 가는 일과 식탁에 앉는 일이 한 장면에 있습니다. 그다음 모세는 홀로 구름 속으로 들어가 사십 일 동안 산에 머뭅니다(24:15~18). 하나님의 영광은 맹렬한 불처럼 산꼭대기에 머물러 있었다고 적습니다(24:17)."
