          "이어서 모세가 하나님과 나누는 대화에서 이 연재의 제목이 나왔습니다. 모세는 하나님이 주신 은총의 말씀에 기대어 주의 길을 알려 달라고 청합니다(33:12~13). 하나님은 내 얼굴이 함께 가겠고 너를 쉬게 하겠다고 하십니다(33:14). 모세는 주의 얼굴이 함께 가시지 않으려거든 우리를 이곳에서 올려 보내지 말아 달라고 말합니다(33:15). 그리고 이 백성이 땅의 모든 백성과 구별되는 것은 하나님이 함께 가시는 것으로 알려진다고 말합니다(33:16). 땅이 약속되어도 하나님의 임재 없이는 가지 않겠다는 말입니다. 3장에서 하나님이 하신 내가 함께 있겠다는 약속에 대한 모세의 대답처럼 읽힙니다. 하나님은 모세가 청한 이 일도 하겠다고 하십니다(33:17).",
          "모세는 한 걸음 더 나아가 주의 영광을 보여 달라고 청합니다(33:18). 하나님은 자신의 선한 모든 것을 지나가게 하고 이름을 선포하겠다고 하시지만, 사람이 얼굴을 보고는 살 수 없다고 하시며 얼굴은 보이지 않으십니다(33:19~20). 대신 모세를 바위 틈에 두고 손으로 덮은 채 지나가시고, 지나간 뒤에 등을 보게 하겠다고 하십니다(33:21~23). 모세는 하나님과 가장 가까이 있는 사람인데도 하나님의 전부를 보지는 못합니다. 가까이 계심과 다 알 수 없는 신비가 한 장 안에 함께 있습니다. 다음 장에서 하나님은 이름을 선포하십니다."
