          "마리아는 산골에 사는 엘리사벳을 찾아갑니다. 인사를 듣자 엘리사벳의 뱃속 아이가 뛰놀고, 엘리사벳은 성령이 충만하여 마리아를 복되다고 하며, 주의 말씀이 이루어지리라고 믿은 여자는 복되다고 말합니다(1:39~45). 마리아는 노래합니다. 하나님이 낮은 여종을 돌아보셨다고 하며(1:48), 권세 있는 사람을 내리시고 낮은 사람을 높이시며 주린 사람을 좋은 것으로 채우신다고 노래합니다(1:52~53). 노래의 끝은 하나님이 자비를 기억하시고 아브라함과 그 자손에게 하신 약속을 이루셨다는 것입니다(1:54~55). 마리아의 노래는 자기 이야기로 시작해 하나님이 이스라엘 전체를 돌아보신 이야기로 넓어집니다. 마리아는 석 달쯤 엘리사벳과 함께 머문 뒤 돌아갑니다(1:56)."
