          "한 백부장의 종이 병들어 죽게 되자 유대 장로들이 예수께 와서, 이 사람은 우리 민족을 사랑하고 회당을 지어 주었으니 도와 달라고 청합니다(7:1~5). 백부장은 친구들을 보내 집에 오시는 것도 감당할 수 없으니 말씀만 하시라고 합니다. 자기도 권위 아래 있는 사람이어서 명령하면 이루어지는 것을 안다는 말입니다(7:6~8). 예수께서는 놀라며 이스라엘에서도 이런 믿음을 보지 못했다고 하십니다. 종은 나아 있었습니다(7:9~10). 이어서 나인 성에서 장례 행렬을 만나 홀로된 어머니가 아들을 잃은 모습을 보시고 불쌍히 여겨 울지 말라고 하시며, 관에 손을 대고 청년에게 일어나라고 하십니다. 청년이 일어나 말을 하자 사람들은 하나님이 자기 백성을 돌보셨다고 말합니다(7:11~17). 예수께서는 부탁받기 전에 먼저 보시고 움직이십니다.",
