          "바리새인 시몬이 예수를 식사에 초대한 집에, 그 동네에서 죄인으로 알려진 여자가 향유 병을 들고 들어옵니다. 여자는 예수의 발 곁에서 울며 눈물로 발을 적시고 머리털로 닦고 입 맞추며 향유를 붓습니다(7:36~38). 시몬이 속으로 이 사람이 예언자라면 이 여자가 누구인지 알 텐데 하고 생각하자(7:39), 예수께서는 빚진 두 사람의 비유를 들려주십니다. 한 사람은 오백, 한 사람은 오십을 탕감받았는데 누가 더 사랑하겠느냐는 물음입니다(7:40~43). 예수께서는 시몬이 해 주지 않은 대접과 여자가 한 일을 견주신 뒤, 여자에게 네 죄가 사해졌고 네 믿음이 너를 구원했으니 평안히 가라고 하십니다(7:44~50). 이 장에서 예수께서 믿음이라고 부르시는 것은 높은 자리의 사람이 아니라 백부장과 이름난 죄인에게서 나옵니다. 8장 1~3절은 예수께서 열두 제자와, 병 고침을 받은 여러 여자들과 함께 마을을 다니셨다고 적습니다."
