          "예수께서 홀로 기도하시고 제자들이 곁에 있을 때 물으십니다. 무리가 나를 누구라 하느냐. 제자들은 세례 요한이라고도 하고 엘리야라고도 하고 옛 예언자 가운데 한 사람이 살아났다고도 한다고 말합니다(9:18~19). 그러자 예수께서는 같은 질문을 제자들에게로 돌리십니다. 너희는 나를 누구라 하느냐. 베드로가 하나님의 그리스도라고 대답합니다(9:20). 예수께서는 이 사실을 아무에게도 말하지 말라고 당부하시고, 인자가 많은 고난을 받고 장로들과 대제사장들과 율법학자들에게 버림받아 죽임을 당하고 사흘째 다시 살아나야 한다고 하십니다(9:21~22). 그리고 누구든지 나를 따르려면 자기를 부인하고 날마다 자기 십자가를 지고 따라야 한다고 하십니다(9:23). 헤롯은 이 사람이 누구냐고 물었고, 무리는 이 사람이 누구라고 말했고, 예수께서는 제자들에게 너희는 누구라고 하느냐고 물으십니다. 같은 질문이 세 곳에서 나옵니다(9:9; 9:18~20).",
          "그 뒤 예수께서는 베드로와 요한과 야고보를 데리고 기도하러 산에 올라가십니다. 기도하시는 동안 얼굴 모양이 달라지고 옷이 희게 빛납니다(9:28~29). 모세와 엘리야가 영광 가운데 나타나 예수께서 예루살렘에서 이루실 떠나심을 이야기합니다(9:30~31). 떠나심으로 옮긴 낱말은 출애굽기라는 책 이름과 같은 낱말입니다. 이스라엘이 이집트에서 나온 이야기를 따라온 사람에게는 낯설지 않은 말입니다. 베드로가 초막 셋을 짓자고 하는 동안 구름이 와서 그들을 덮고(9:33~34), 구름 속에서 이는 내 아들, 택함 받은 자이니 그의 말을 들으라는 소리가 납니다(9:35). 소리가 그치자 예수만 홀로 계십니다(9:36). 시내산을 덮은 구름(출애굽기 24:15~18)과 성막을 덮은 구름(출애굽기 40:34)을 떠올리는 이가 많습니다.",
