          "무리 가운데 한 사람이 형제에게 유산을 나누라고 말해 달라고 청합니다(12:13). 예수께서는 누가 나를 재판관이나 나누는 사람으로 세웠느냐고 하시고, 모든 탐욕을 조심하라며 소유가 넉넉하다고 삶이 거기서 나오는 것은 아니라고 하십니다(12:14~15). 비유 속에서 한 부자의 밭이 풍성한 소출을 냅니다. 부자는 지금의 곳간을 허물고 더 큰 곳간을 지어 곡식과 재물을 쌓은 뒤, 자기 영혼에게 앞으로 오랫동안 넉넉하니 편히 먹고 마시며 즐기라고 말하겠다고 합니다(12:16~19). 하나님은 그에게 어리석은 사람아, 오늘 밤 네 영혼이 너에게서 요구될 것이니 네가 모은 것이 누구에게 돌아가겠느냐고 하십니다. 자기를 위해 모으면서 하나님 앞에서는 부유하지 못한 사람이 이와 같다는 말씀입니다(12:20~21). 이 비유를 재산이 있는 사람 모두를 향한 말로 읽지 않습니다.",
