          "한 부자는 값비싼 옷을 입고 날마다 잘 먹고 지냅니다(16:19). 나사로라는 거지는 헌데투성이로 부자의 대문 앞에 누워 부자의 상에서 떨어지는 것으로 배를 채우려 하고, 개들이 와서 그의 헌데를 핥습니다(16:20~21). 거지가 죽어 천사들에게 이끌려 아브라함의 품에 안기고, 부자도 죽어 묻힙니다(16:22). 음부에서 고통 가운데 눈을 들어 멀리 아브라함과 그 품의 나사로를 본 부자는 나사로를 보내 손가락에 물을 찍어 혀를 시원하게 해 달라고 청합니다(16:23~24). 아브라함은 살아 있을 때 누린 좋은 것과 나사로가 겪은 나쁜 것을 말한 뒤 이제는 자리가 뒤바뀌었다고 하고, 여기와 거기 사이에 큰 틈이 놓였다고 말합니다(16:25~26). 본문은 나사로의 가난과 병의 까닭을 적지 않고, 부자가 대문 앞의 나사로에게 어떻게 했는지도 직접 적지 않습니다. 부자는 다섯 형제에게 나사로를 보내 경고해 달라고 청하지만, 아브라함은 모세와 예언자가 있으니 그들의 말을 들으라고 하고, 그 말을 듣지 않으면 죽은 사람이 살아나도 믿지 않는다고 합니다(16:27~31). 음부와 아브라함의 품과 큰 틈을 죽은 뒤의 상태를 그린 말로 읽을지, 비유 안의 이야기로 읽을지는 교회마다 이해가 다릅니다."
