        "look": "예수께서 과부와 재판관 이야기를 하신 까닭과 두 사람이 각각 하는 말을 읽으십시오. 예수께서는 이 이야기 뒤에 무엇을 말씀하십니까? 성전에서 기도한 바리새인과 세리가 각각 서 있는 모습과 기도를 찾으십시오. 예수께서는 이 이야기를 누구에게 하셨으며 마지막에 무엇이라 말씀하십니까? 아이들과 한 관리와 맹인에게 예수께서 하신 말씀과 일을 하나씩 읽으십시오.",
