          "예수께서 낙심하지 말고 항상 기도해야 한다는 뜻으로 비유를 하십니다(18:1). 한 도시에 하나님도 두려워하지 않고 사람도 존중하지 않는 재판관이 있고, 한 과부가 찾아와 자기 원수에 대해 판결해 달라고 합니다(18:2~3). 재판관은 한동안 들어주지 않다가, 이 과부가 자꾸 귀찮게 하니 판결해 주겠다고 속으로 말합니다(18:4~5). 예수께서는 불의한 재판관의 말을 들으라고 하시고, 하나님이 밤낮 부르짖는 자기 사람들을 오래 참으시더라도 정의를 베풀어 주시지 않겠느냐고 물으십니다. 속히 그렇게 하시리라고 하시고, 인자가 올 때 땅에서 믿음을 보겠느냐고 하십니다(18:6~8). 이 비유를 구하면 반드시 이루어진다는 약속으로만 읽지 않습니다. 기도가 이루어지지 않는 때를 어떻게 이해할지는 교회마다 이해가 다르며, 이루어지지 않는 일을 기도하는 사람의 믿음 탓으로 잇지 않습니다.",
          "예수께서는 자기가 의롭다고 믿고 다른 사람들을 업신여기는 몇 사람에게 비유를 하십니다(18:9). 바리새인과 세리 두 사람이 기도하러 성전에 올라갑니다(18:10). 바리새인은 서서 따로 기도하며, 다른 사람들과 같지 않음을 하나님께 감사하고 일주일에 두 번 금식하며 소득의 십일조를 낸다고 말합니다(18:11~12). 세리는 멀리 서서 눈을 들지 못하고 가슴을 치며 죄인인 나에게 자비를 베푸소서 하고 기도합니다(18:13). 예수께서는 이 사람이 의롭다고 인정받고 집으로 내려갔다고 하시며, 스스로 높이는 이는 낮아지고 스스로 낮추는 이는 높아진다고 하십니다(18:14). 본문은 바리새인이 한 금식과 십일조를 틀렸다고 말하지 않습니다. 이 비유를 바리새인 모두가 교만하다는 말로 읽지 않으며, 본문은 비유를 하시는 대상을 자기가 의롭다고 믿는 몇 사람이라고 먼저 밝힙니다(18:9).",
          "사람들이 아기들을 데려와 만져 달라고 하자 제자들이 꾸짖고, 예수께서는 아이들을 오게 하시며 하나님 나라가 이런 사람들의 것이라고 하십니다(18:15~17). 한 관리가 선한 선생님이라 부르며 영원한 생명을 얻으려면 무엇을 해야 하느냐고 묻습니다. 예수께서는 왜 나를 선하다고 하느냐 선하신 분은 하나님 한 분뿐이라고 하시고 계명을 말씀하십니다(18:18~20). 그가 어려서부터 다 지켰다고 하자, 예수께서는 아직 한 가지가 부족하다 가진 것을 팔아 가난한 사람들에게 나누어 주고 와서 나를 따르라고 하십니다(18:21~22). 그는 큰 부자라 이 말씀을 듣고 몹시 근심합니다(18:23). 예수께서는 재물 있는 사람이 하나님 나라에 들어가기는 어렵다고 하시고, 사람에게 불가능한 것이 하나님께는 가능하다고 하십니다(18:24~27). 베드로가 우리는 우리 것을 두고 따랐다고 하자, 하나님 나라를 위해 집과 가족을 떠난 사람은 이 세상에서 여러 배를 받고 오는 세상에서 영원한 생명을 받는다고 하십니다(18:28~30). 이 말씀을 오늘 모든 사람에게 재산을 처분하라는 명령으로 읽을지 이 사람에게 하신 말씀으로 읽을지는 교회마다 이해가 다릅니다. 여러 배를 받는다는 말은 거래나 번영의 약속으로 읽지 않습니다.",
          "예수께서 열두 제자를 따로 데리고 예루살렘으로 올라가 인자가 이방 사람들에게 넘겨져 조롱과 해를 당하고 죽임을 당했다가 사흘째 살아나리라고 하십니다. 제자들은 이 말씀 가운데 아무것도 깨닫지 못합니다(18:31~34). 예수께서 여리고에 가까이 가실 때 길가에 앉아 구걸하던 맹인이 지나가시는 분이 나사렛 예수라는 말을 듣고, 다윗의 자손 예수여 불쌍히 여겨 달라고 부르짖습니다(18:35~38). 앞서가는 사람들이 잠잠하라고 하지만 그는 더 크게 부르짖고(18:39), 예수께서 서서 그를 데려오게 하시고 무엇을 원하느냐고 물으십니다(18:40~41). 그가 보게 해 달라고 하자 예수께서는 보라, 네 믿음이 너를 구원했다고 하시고, 그는 곧 보게 되어 하나님께 영광을 돌리며 예수를 따르고 모든 백성도 하나님을 찬양합니다(18:42~43). 이 말씀을 병이 낫지 않은 사람의 믿음이 모자라서라는 말로 쓰지 않습니다."
