          "예수께서 예루살렘에 가까이 오셨고 사람들이 하나님 나라가 곧 나타나리라고 생각했기 때문에 비유를 하십니다(19:11). 한 귀인이 왕위를 받으러 먼 나라로 가며, 종 열 사람에게 한 므나씩(큰돈의 단위) 주고 돌아올 때까지 장사하라고 합니다(19:12~13). 그 나라 사람들은 이 사람이 우리의 왕이 되는 것을 원하지 않는다고 사절을 보냅니다(19:14). 귀인이 왕위를 받고 돌아와 종들에게 결산을 받습니다. 첫째는 열 므나를 더 남겼고, 둘째는 다섯 므나를 더 남겼으며, 각각 열 고을과 다섯 고을을 맡습니다(19:15~19). 다른 종은 받은 므나를 수건에 싸 두었다가 주인이 엄한 사람이라 무서웠다고 말하고, 주인은 그의 므나를 빼앗아 열 므나 가진 사람에게 주라고 합니다(19:20~24). 가진 사람은 더 받고 없는 사람은 가진 것까지 빼앗긴다는 말도 나옵니다(19:25~26). 끝으로 왕이 되기를 원하지 않던 사람들을 데려다 자기 앞에서 처단하라는 말이 있습니다(19:27). 이 비유를 잘 투자하면 더 받는다는 번영의 법칙으로 읽지 않으며, 마태복음 25:14~30에도 비슷한 이야기가 있지만 같지 않습니다.",
          "비유를 마치고 예수께서 앞서 예루살렘으로 올라가십니다(19:28). 감람산 쪽 마을에서 제자 둘이 새끼 나귀를 끌어오고, 예수께서 그 위에 오르시며 사람들은 겉옷을 길에 폅니다(19:29~36). 감람산 내리막에서 제자의 온 무리가 기뻐하며 큰 소리로 하나님이 보내신 왕이라고 찬양합니다(19:37~38). 바리새인 몇이 제자들을 꾸짖으라고 하자, 예수께서는 사람들이 입을 다물면 돌들이 외칠 것이라고 하십니다(19:39~40). 예루살렘이 보이는 곳에서 예수께서 우시며 평화에 관한 것을 알았더라면 하고 말씀하시고, 원수들이 에워싸고 돌 하나도 돌 위에 남지 않게 할 날이 이를 것이라고 하십니다(19:41~44). 이 말씀이 뒤에 일어난 어느 일을 가리키는지는 본문이 적지 않으며 교회마다 이해가 다릅니다. 유대 사람 전체를 향한 하나님의 판결로 읽지도 않습니다.",
