        "look": "성전을 두고 사람들이 한 말과 예수께서 하신 말씀을 읽으십시오. 제자들은 무엇을 묻고, 예수께서는 맨 먼저 무엇을 조심하라고 하십니까? 이 모든 일 전에 제자들에게 있을 일과 예수께서 주시겠다고 하신 것을 찾으십시오. 예루살렘에 관한 말씀, 하늘의 징조와 인자에 관한 말씀, 무화과나무 이야기, 마지막 당부를 순서대로 읽으십시오. 예수께서 낮과 밤을 어떻게 지내시는지도 보십시오.",
        "ask": "어지러운 소식 앞에서 내 마음은 어디로 쏠리며, 오늘 깨어 있다는 것은 내게 어떤 모습입니까?",
