          "제자들 사이에 누가 가장 큰 사람으로 여겨질지를 두고 다툼이 일어납니다(22:24). 예수께서는 이방 사람들의 왕은 사람들을 주관하지만 너희는 그렇지 않다고 하시고, 너희 가운데서는 큰 사람일수록 가장 어린 사람처럼, 이끄는 사람일수록 시중드는 사람처럼 되라고 하십니다(22:25~26). 식탁에 앉은 사람과 시중드는 사람 가운데 누가 더 크냐고 물으시고, 자신은 시중드는 사람으로 그들 가운데 있다고 하시고(22:27), 시험 가운데서도 함께한 제자들에게 나라를 맡기겠다고 하십니다(22:28~30). 시몬아 시몬아 하고 부르시며, 사탄이 너희를 알곡처럼 흔들어 보려고 청했으나 네 믿음이 꺾이지 않도록 내가 기도했다고 하시고, 네가 돌아선 뒤에는 형제들을 굳게 하라고 하십니다(22:31~32). 시몬이 주와 함께 옥에도 죽는 데도 가겠다고 하자, 예수께서는 오늘 닭이 울기 전에 네가 나를 세 번 모른다고 하리라고 하십니다(22:33~34). 이어 전대와 배낭과 칼 이야기를 하시고, 제자들이 여기 칼 둘이 있다고 하자 족하다고 하십니다(22:35~38). 이 말씀의 뜻과 오늘의 적용은 교회마다 이해가 다릅니다.",
