          "빌라도가 대제사장들과 관리들과 백성을 불러 모아, 너희가 이 사람을 고발한 일에서 죄를 찾지 못했고 헤롯도 그러하다고 말하고, 때려서 놓아주겠다고 합니다(23:13~16). 무리가 일제히 이 사람을 없애고 바라바를 놓아 달라고 소리 지릅니다. 바라바는 성안에서 일어난 민란과 사람을 해친 일로 옥에 갇힌 사람입니다(23:18~19). 빌라도가 예수를 놓아주려고 다시 말하지만 사람들은 십자가에 못 박으라고 소리치고, 세 번째로 무슨 악한 일을 했느냐 죽일 죄를 찾지 못했다고 하는데도 그들은 큰 소리로 요구하여 그 소리가 이깁니다(23:20~23). 빌라도는 그들이 구하는 대로 하기로 판결하고, 바라바를 놓아주고 예수를 그들의 뜻대로 하게 넘깁니다(23:24~25). 본문은 소리친 사람들을 그들이라고만 적으며, 그 앞에는 대제사장들과 관리들과 백성을 불러 모은 자리가 있습니다(23:13). 이 장면을 유대 민족 전체의 책임으로 읽지 않으며, 역사 속에서 이 장면이 잘못 쓰인 일이 있었습니다."
