    "intro": "마태복음은 계보로 문을 엽니다. 다윗과 아브라함의 자손으로 소개된 예수께서 나셨을 때 동방에서 온 사람들은 왕으로 나신 분이 어디 계신지 묻고, 헤롯 왕과 예루살렘은 소동합니다. 이어 광야의 시험과 산 위의 가르침, 치유와 파송, 쉼으로의 초청, 안식일 논쟁, 하늘나라 비유가 이어지는 동안 사람들은 이분이 누구냐고 거듭 묻습니다. 마태가 구약의 말씀을 이어 오는 곳마다 출처를 함께 살피면서, 이분이 어떤 왕으로 그려지는지 눈여겨보십시오.",
