          "마태는 이 일을 예언자가 한 말이 이루어진 것이라고 합니다. 신약은 이렇게 잇습니다(마태복음 1:22~23, 이사야 7:14). 아이의 이름 임마누엘은 본문이 하나님이 우리와 함께 계시다는 뜻이라고 풀어 줍니다(1:23). 이사야서의 본래 자리에서 이 말씀이 누구를 가리켰는지, 마태가 옮긴 낱말을 어떻게 이해할지는 교회와 학자마다 다릅니다. 1장 25절이 요셉과 마리아의 그 뒤 일을 어떻게 말해 주는지도 교회마다 이해가 다릅니다. 책의 첫 장에서 아이에게 붙는 두 이름은 예수와 임마누엘이고, 하나는 구원을, 하나는 함께 계심을 말합니다(1:21; 1:23)."
