          "예수께서 헤롯 왕 때 유대 베들레헴에서 나셨고, 동방에서 온 사람들이 예루살렘에 와서 유대 사람의 왕으로 나신 분이 어디 계신지 묻습니다. 자기들이 동쪽에서 그의 별을 보았고 경배하러 왔다고 합니다(2:1~2). 한국 교회에서는 이들을 흔히 동방박사라 부르지만, 본문은 이들의 나라나 사람 수나 왕이라는 신분을 적지 않습니다. 이들이 드린 선물이 황금과 유향과 몰약이라는 것만 적습니다(2:11). 헤롯 왕은 이 말을 듣고 소동했고 예루살렘 사람들도 그와 함께 그러했습니다(2:3). 헤롯은 대제사장들과 서기관들을 모아 그리스도가 어디서 나시는지 묻고, 그들은 베들레헴이라 답하며 예언자의 말을 듭니다(2:4~6). 신약은 이렇게 잇습니다(마태복음 2:5~6, 미가 5:2, 사무엘하 5:2의 말도 섞여 있습니다). 본문은 대답한 사람들이 그 뒤 어떻게 했는지는 적지 않습니다.",
