          "이어 같은 틀의 말씀이 여섯 번 나옵니다. 사람들이 들은 말을 꺼내신 뒤 자기 말씀을 잇는 모양입니다(5:21~22; 5:27~28; 5:31~32; 5:33~34; 5:38~39; 5:43~44). 살인과 분노, 형제와 화해하는 일(5:21~26), 간음과 탐하는 눈, 몸의 한 부분을 잃더라도 온몸이 지옥에 던져지지 않는 편이 낫다는 강한 말씀(5:27~30), 이혼증서와 음행이 아닌 이유로 아내를 내보내는 일(5:31~32), 맹세하지 말라는 말씀(5:33~37), 눈에는 눈이라는 옛말과 악에 맞서지 말라는 말씀(5:38~42), 이웃은 사랑하고 원수는 미워하라는 말과 원수를 사랑하라는 말씀(5:43~48)이 이어집니다. 이 틀을 예수께서 모세의 율법을 낮추신 것으로 읽지 않고 율법의 뜻을 더 깊이 밝히신 것으로 읽는 교회가 있고, 달리 읽는 교회도 있습니다. 5장 43절의 뒷말은 구약 율법에 그대로 나오지 않는 말이라 무엇을 가리키는지도 이해가 갈립니다. 유대교의 가르침을 낮추는 틀로 읽지 않도록 주의합니다.",
          "여섯 말씀 가운데 이해가 갈리는 곳이 있습니다. 5:31~32에서 이혼과 재혼을 어떻게 볼지, 음행이 아닌 이유라는 예외를 어떻게 읽을지는 교회마다 이해가 다릅니다. 5:33~37의 맹세하지 말라는 말씀을 법정의 선서에 어떻게 적용할지도 교회마다 다릅니다. 5:38~42를 폭력이나 학대 앞에서 오늘 어떻게 읽을지, 5:22와 5:29~30에서 지옥으로 옮긴 말이 무엇을 가리키는지도 교회마다 이해가 다릅니다. 이 장은 원수를 사랑하고 박해하는 사람을 위해 기도하라는 말씀으로 이어지며, 아버지는 해를 악한 사람과 선한 사람 위에 뜨게 하시고 비를 의로운 사람과 불의한 사람 위에 내리신다고 합니다(5:44~45). 끝에서 하늘 아버지가 온전하신 것처럼 너희도 온전하라고 하십니다(5:48). 온전함이 흠이 없음인지 성숙함인지는 교회마다 이해가 다르며, 이 말씀을 스스로를 몰아세우는 점수표로 쓰지 않습니다."
