          "그다음에는 문과 길 이야기입니다. 넓은 문과 큰 길은 멸망으로 이끌고 들어가는 사람이 많고, 좁은 문과 좁은 길은 생명으로 이끌고 찾는 사람이 적다고 합니다(7:13~14). 많고 적음이 구원받는 사람의 수를 알려 주는 말인지는 교회마다 이해가 다릅니다. 양의 옷을 입은 거짓 예언자는 열매로 알아본다고 하십니다(7:15~20). 이어 주여 주여 하는 사람마다 하늘나라에 들어가는 것이 아니라 아버지의 뜻을 행하는 사람이 들어간다고 하십니다(7:21). 그날에 많은 사람이 예언하고 귀신을 쫓고 능력을 행했다고 말하지만 나는 너희를 알지 못한다고 답하겠다고 하십니다(7:22~23). 이 경고가 이미 믿는 사람도 구원을 잃을 수 있다는 뜻인지, 말과 겉모습만 있는 신앙을 두고 한 말인지는 교회마다 이해가 다릅니다. 이 말씀으로 이웃이나 나의 구원을 판정하지 않습니다.",
