          "예수께서 세관에 앉아 있는 마태라는 사람을 보시고 나를 따르라고 하시자, 마태가 일어나 따릅니다(9:9). 예수께서 집에서 식사하실 때 많은 세리와 죄인이 와서 예수와 제자들과 함께 앉습니다(9:10). 이를 본 바리새인들이 제자들에게 왜 당신들의 선생은 세리와 죄인과 함께 먹느냐고 묻습니다(9:11). 예수께서는 듣고 건강한 사람에게는 의사가 필요 없고 병든 사람에게 필요하다고 하시고, 가서 배우라며 내가 원하는 것은 자비이고 제사가 아니라고 하십니다(9:12~13). 신약은 이렇게 잇습니다(마태복음 9:13, 호세아 6:6). 본문은 그 자리에서 바리새인들이 제자들에게 던진 물음을 적을 뿐이며, 바리새인 전체에 대한 평가로 읽지 않습니다. 이어 요한의 제자들이 우리와 바리새인들은 금식하는데 왜 당신의 제자들은 하지 않느냐고 묻자, 예수께서는 신랑이 함께 있는 동안 손님이 슬퍼하겠느냐고 하시며 신랑을 빼앗길 날이 오면 금식할 것이라고 하십니다(9:14~15). 새 천 조각과 낡은 옷, 새 포도주와 낡은 가죽 부대의 비유도 이어지지만 본문은 풀이를 달지 않습니다(9:16~17).",
