        "look": "안식일에 제자들은 무엇을 했고 바리새인들은 무엇이라 말합니까? 예수께서는 어떤 이야기들을 들어 답하시고 마지막에 자신을 무엇이라 하십니까? 손이 마른 사람 앞에서 사람들이 묻는 말과 예수께서 드시는 비유는 무엇입니까? 눈멀고 말 못하던 사람이 고쳐진 뒤 무리와 바리새인들은 각각 무엇이라 말합니까? 요나의 표적에 대해 예수께서는 무엇이라 하십니까? 마지막에 예수께서는 누구를 가리켜 어머니와 형제라 하십니까?",
