          "이어 예수께서 여러 하늘나라 비유를 말씀하십니다. 좋은 씨를 뿌린 밭에 사람들이 잠든 사이 원수가 가라지를 덧뿌리고 갔습니다. 종들이 가라지를 뽑을까 묻자 주인은 가라지를 뽑다가 곡식까지 뽑을까 염려되니 추수 때까지 함께 자라게 두라고 합니다(13:24~30). 이어 겨자씨 비유(13:31~32)와 누룩 비유(13:33)가 나옵니다. 마태는 예수께서 무리에게 비유로만 말씀하신 것을 시편의 말씀과 잇습니다. 신약은 이렇게 잇습니다(마태복음 13:34~35, 시편 78:2). 예수께서 무리를 보내고 집에 들어가시자 제자들이 가라지 비유를 설명해 달라고 합니다. 좋은 씨는 나라의 아들들, 가라지는 악한 자의 아들들, 원수는 마귀, 추수는 세상 끝, 추수꾼은 천사들이며, 세상 끝에 인자가 천사들을 보내 불의를 행하는 사람들을 모아 불 풀무에 던지고 의인들은 아버지 나라에서 해처럼 빛난다고 하십니다(13:36~43). 8장 12절에서도 같은 말 나라의 아들들이 나오는데 거기서는 쫓겨나는 쪽에 쓰입니다. 두 곳이 같은 사람들을 가리키는지는 교회마다 이해가 다릅니다. 누가 가라지인지 가려내는 일을 본문은 사람에게 맡기지 않고 추수 때까지 두라고 합니다(13:28~30). 심판의 모습은 교회마다 이해가 다릅니다.",
