          "예루살렘이 가까워 감람산 벳바게에 이르렀을 때, 예수께서는 두 제자를 보내시며 맞은편 마을에 매어 있는 나귀와 새끼를 풀어 오라고, 누가 묻거든 주께서 쓰시겠다고 하라고 하십니다(21:1~3). 마태는 이 일이 예언자의 말씀을 이룬 것이라고 하며, 시온의 딸에게 왕이 겸손하여 나귀를 타고 온다는 말을 적습니다. 신약은 이렇게 잇습니다(마태복음 21:4~5, 스가랴 9:9; 이사야 62:11). 제자들이 말씀하신 대로 하고 겉옷을 나귀에 얹으며(21:6~7), 큰 무리는 겉옷과 나뭇가지를 길에 펴고(21:8), 앞서고 뒤따르는 무리가 다윗의 자손에게 호산나를 외치며 주의 이름으로 오시는 분을 축복하고, 가장 높은 곳에서도 호산나를 외칩니다. 신약은 이렇게 잇습니다(마태복음 21:9, 시편 118:25~26). 온 성이 술렁여 이 사람이 누구냐고 묻자 무리는 갈릴리 나사렛에서 온 예언자 예수라고 합니다(21:10~11). 예수께서는 성전에 들어가 팔고 사는 사람들을 모두 내쫓으시고, 환전하는 사람들의 상과 비둘기 파는 사람들의 의자를 엎으십니다(21:12). 기록된 말씀에서 하나님의 집은 기도하는 곳으로 불리는데 너희는 그곳을 강도들이 숨는 곳처럼 만들었다고 하십니다. 신약은 이렇게 잇습니다(마태복음 21:13, 이사야 56:7; 예레미야 7:11). 성전에서 눈먼 사람과 저는 사람이 나아오자 고치시고(21:14), 대제사장들과 서기관들은 놀라운 일과 아이들이 호산나 하고 외치는 것을 보고 노하여 이 말이 들리느냐고 묻습니다(21:15~16). 예수께서는 아이들과 젖먹이의 입에서 찬양이 나오게 하셨다는 말씀을 읽지 못했느냐고 답하십니다. 신약은 이렇게 잇습니다(마태복음 21:16, 시편 8:2). 그러고는 성을 떠나 베다니에서 지내십니다(21:17). 이 일을 성전이나 유대교 전체를 향한 판결로 읽지 않으며, 본문이 가리키는 것은 팔고 사는 일이 이루어지던 그 자리입니다. 교회가 오늘 헌금이나 판매를 어떻게 할지 정하는 말씀으로도 읽지 않습니다.",
          "아침에 성으로 돌아오시다가 예수께서는 배가 고프셨고(21:18), 길가의 무화과나무에 가 보시니 잎사귀밖에 없어서 이제부터 영원히 열매를 맺지 못하라고 하시자 나무가 곧 말랐다고 본문은 적습니다(21:19). 제자들이 놀라 어떻게 곧 말랐느냐고 묻자(21:20), 예수께서는 믿고 의심하지 않으면 이 무화과나무에 한 일뿐 아니라 이 산더러 바다에 빠지라고 해도 이루어질 것이며, 믿고 기도하며 구하는 것은 다 받을 것이라고 하십니다(21:21~22). 이 나무에게 열매를 맺지 못하라고 하신 일이 무엇을 가리키는지는 본문이 설명하지 않으며, 교회마다 이해가 다릅니다. 이 이야기로 이스라엘이 저주받았다고 읽지 않습니다. 기도에 관한 말씀을 오늘 기도의 응답을 보장하는 법칙처럼 읽지 않으며, 이루어지지 않은 기도를 믿음이 모자란 탓으로 잇지 않습니다.",
          "성전에서 가르치실 때 대제사장들과 백성의 장로들이 무슨 권위로 이런 일을 하느냐고 묻자(21:23), 예수께서는 요한의 세례가 하늘에서 왔느냐 사람에게서 왔느냐고 되물으십니다(21:24~25). 그들은 서로 의논하다가 모른다고 답하고, 예수께서도 무슨 권위로 이 일을 하는지 말하지 않겠다고 하십니다(21:25~27). 이어 두 아들 비유를 말씀하십니다. 한 사람이 두 아들에게 포도원에 가서 일하라고 했는데, 첫째는 싫다고 했다가 뉘우치고 갔고, 둘째는 가겠다고 하고 가지 않았습니다. 누가 아버지의 뜻을 행했느냐는 물음에 대제사장들과 장로들은 첫째라고 답합니다(21:23, 21:28~31). 예수께서는 세리 등이 하나님 나라에 먼저 들어간다고 하시며, 요한이 의의 길로 왔을 때 너희는 믿지 않았고 세리 등은 믿었으며, 너희는 보고도 뉘우치지 않았다고 하십니다(21:31~32). 여기서 너희는 앞의 물음에 답한 대제사장들과 장로들입니다.",
          "이어 다른 비유를 말씀하십니다. 한 집 주인이 포도원을 만들어 울타리를 치고 즙 짜는 틀과 망대를 세워 농부들에게 맡기고 멀리 떠납니다(21:33). 열매 철에 종들을 보내자 농부들은 종들을 해쳤고, 더 많은 종을 보내도 같게 하였습니다(21:34~36). 마지막으로 아들을 보내며 아들은 존중하리라고 하나, 농부들은 아들을 보고 상속자이니 죽이고 상속을 차지하자고 하며 포도원 밖으로 내쫓아 해칩니다(21:37~39). 주인이 돌아오면 농부들을 어떻게 하겠느냐는 물음에 사람들은 그 악한 사람들을 비참하게 없애고, 철에 따라 열매를 바치는 다른 농부들에게 포도원을 맡기겠다고 답합니다(21:40~41). 예수께서는 건축하는 사람들이 내버린 돌이 모퉁이의 으뜸 돌이 되었다는 말씀을 읽지 못했느냐고 하십니다. 신약은 이렇게 잇습니다(마태복음 21:42, 시편 118:22~23). 이어 하나님 나라가 너희에게서 빼앗겨 열매 맺는 백성에게 주어질 것이라고 하십니다(21:43). 대제사장들과 바리새인들은 이 비유가 자기들을 두고 하신 말씀인 줄 알고 예수를 잡으려 하나 무리를 두려워합니다(21:45~46). 비유 속 아들을 예수와 이어 읽는 것은 교회가 오래 이어 온 읽기이며, 본문은 비유 안에서 그 이름을 말하지 않습니다. 열매 맺는 백성이 누구인지, 이 말씀이 교회가 이스라엘을 대신한다는 뜻인지는 교회마다 이해가 다릅니다. 본문은 대제사장들과 바리새인들이 이 말씀을 자기들을 두고 하신 것으로 알아들었다고 적으며(21:45), 유대 사람 전체를 향한 말씀으로 읽지 않습니다."
