          "이어 예수께서는 서기관과 바리새인들을 위선자라 부르시며 화가 있다고 하십니다. 하늘나라를 사람들 앞에서 닫고 자기도 들어가지 않으며 들어가려는 사람도 막는다고 하시고(23:13), 한 사람을 얻으려고 바다와 땅을 두루 다니지만 그 결과를 책망하십니다(23:15). 맹세에 관해 성전과 금과 제단을 두고 하는 말을 지적하시고(23:16~22), 박하와 회향과 근채는 십일조로 내면서 율법의 더 무거운 것, 정의와 자비와 신실함은 버렸다고 하시며 이것도 저것도 버리지 말 것이라고 하십니다(23:23). 작은 것은 걸러 내고 큰 것은 삼킨다고 하시고(23:24), 잔과 접시의 겉만 닦고 속은 탐욕과 방탕으로 가득하다고 하시며 속을 먼저 깨끗하게 하라고 하십니다(23:25~26). 회칠한 무덤처럼 겉은 곱게 꾸몄으나 안은 죽은 사람의 뼈와 부정한 것으로 차 있다고도 하십니다(23:27~28). 본문은 십일조를 버리라고 하지 않고 이것도 저것도 버리지 말 것이라고 하며, 오늘 십일조를 어떻게 할지는 교회마다 이해가 다릅니다.",
          "예언자들의 무덤을 짓고 의인들의 기념비를 꾸미며 우리가 조상 때 있었다면 예언자들을 해치는 일에 가담하지 않았을 것이라고 말하지만(23:29~30), 그렇게 말하는 것으로 너희는 예언자들을 해친 사람들의 자손임을 스스로 증언한다고 하십니다(23:31). 조상들이 하던 일의 분량을 채우라고 하시고(23:32), 내가 예언자들과 지혜 있는 사람들과 서기관들을 보내면 그 가운데 어떤 사람은 해치고 어떤 사람은 회당에서 때리고 이 성 저 성으로 쫓을 것이라고 하십니다(23:34). 그래서 의인 아벨의 피부터 사가랴의 피까지 땅에서 흘린 모든 의인의 피가 너희에게 돌아올 것이며 이 모든 일이 이 세대에 닥칠 것이라고 하십니다(23:35~36). 이 세대가 누구를 가리키는지는 교회마다 이해가 다릅니다. 유대 사람 전체나 오늘의 누구를 이 말씀으로 정죄하지 않습니다.",
