        "look": "열 사람은 무엇을 가지고 누구를 맞으러 나갑니까? 슬기로운 사람과 어리석은 사람은 어떻게 다르며, 한밤에 어떤 외침이 들립니까? 문이 닫힌 뒤에 어떤 일이 있고, 예수께서는 마지막에 무엇이라 말씀하십니까? 주인은 떠나기 전에 종들에게 무엇을 맡기며, 어떤 기준으로 나누어 맡깁니까? 종들은 각각 무엇을 하고, 돌아온 주인은 각각에게 무엇이라 말합니까? 인자가 영광으로 오실 때 모든 민족은 어떻게 나뉘며, 오른쪽과 왼쪽 사람들에게 각각 무엇이라 하십니까? 두 무리는 무엇이라 되묻고 예수께서는 어떻게 답하십니까?",
        "ask": "내게 맡겨졌다고 느끼는 것이 있다면, 그것을 어떤 마음으로 대하고 싶습니까?",
        "p": [
          "예수께서는 하늘나라를 등을 들고 신랑을 맞으러 나간 열 사람에 비유하십니다. 다섯은 어리석고 다섯은 슬기로웠으며, 어리석은 사람들은 등만 가지고 기름은 가져가지 않았고, 슬기로운 사람들은 그릇에 기름을 가져갔습니다(25:1~4). 신랑이 늦어지자 모두 졸다가 잠들고(25:5), 한밤중에 신랑이 온다는 소리가 나자 일어나 등을 손질합니다(25:6~7). 어리석은 사람들이 기름을 나누어 달라고 하나 슬기로운 사람들은 우리와 너희에게 모자랄지 모르니 가서 사라고 하고(25:8~9), 그들이 사러 간 사이 신랑이 와서 준비한 사람들은 함께 혼인 잔치에 들어가고 문이 닫힙니다(25:10). 나중에 온 사람들이 주여 열어 달라고 하자 신랑은 너희를 알지 못한다고 답합니다(25:11~12). 그러므로 깨어 있으라, 너희는 그날과 그때를 알지 못한다고 맺으십니다(25:13). 깨어 있으라고 하셨는데 열 사람이 모두 잠들었다는 점이 눈에 띕니다. 기름이 무엇을 가리키는지, 문이 닫힌 뒤의 말이 구원의 안전과 어떤 관계인지는 교회마다 이해가 다릅니다. 이 비유로 서로를 슬기로운 사람과 어리석은 사람으로 나누어 평가하지 않습니다.",
          "하늘나라는 또한 먼 길을 떠나는 사람이 종들을 불러 자기 재산을 맡기는 일과 같다고 하시며, 각자의 능력에 따라 한 사람에게 다섯 달란트, 한 사람에게 두 달란트, 한 사람에게 한 달란트를 주고 떠난다고 하십니다(25:14~15). 다섯을 받은 종은 그것으로 장사하여 다섯을 더 남기고, 두 달란트를 받은 종도 두 달란트를 더 남기나, 한 달란트를 받은 종은 땅을 파고 주인의 돈을 감춥니다(25:16~18). 오랜 뒤 주인이 돌아와 셈을 하자 다섯과 두 달란트를 받은 종은 각각 갑절을 내놓고, 주인은 두 종에게 적은 것에 믿음직했으니 많은 것을 맡기겠다, 주인의 기쁨 안으로 들어오라고 같은 말을 합니다(25:19~23). 한 달란트를 받은 종은 주인이 굳은 사람인 줄 알고 두려워서 땅에 감추었다며 그대로 내놓습니다(25:24~25). 주인은 그를 악하고 게으른 종이라 하며 그 한 달란트를 열 달란트 가진 종에게 주라 하고(25:26~28), 가진 사람은 더 받고 없는 사람은 가진 것까지 빼앗긴다고 하며 쓸모없는 종은 바깥 어둠으로 내쫓으라고 합니다(25:29~30). 본문은 달란트가 오늘의 재능이나 재산인지 풀지 않으며, 한 달란트를 받은 종이 주인을 두려워했다는 말과 주인의 평가를 둘 다 적습니다. 이 비유를 일을 많이 하면 더 큰 복을 받는다는 말로 읽지 않으며, 사람의 성과를 서로 견주는 점수표로 쓰지 않습니다. 가진 사람이 더 받는다는 말씀(25:29)을 오늘의 부와 가난을 설명하는 법칙으로 읽을지, 바깥 어둠이 어떤 곳인지는 교회마다 이해가 다릅니다.",
          "인자가 영광으로 모든 천사와 함께 올 때 영광의 보좌에 앉고, 모든 민족이 그 앞에 모이며, 목자가 양과 염소를 가르듯 사람들을 갈라 양은 오른쪽에, 염소는 왼쪽에 둔다고 하십니다(25:31~33). 임금이 오른쪽 사람들에게 아버지의 복을 받은 사람들아, 세상이 시작될 때부터 너희를 위해 준비된 나라를 물려받으라고 하고(25:34), 그 까닭으로 내가 주릴 때 먹이고 목마를 때 마시게 하고 나그네일 때 맞아들이고 헐벗을 때 입히고 병들었을 때 돌보고 갇혔을 때 찾아왔다고 합니다(25:35~36). 의인들이 주여 언제 그리하였느냐고 묻자(25:37~39), 임금은 내 형제 가운데 가장 낮은 한 사람에게 한 일이 내게 한 일이라고 답합니다(25:40). 왼쪽 사람들에게는 나를 떠나 마귀와 그에게 속한 존재들을 위해 마련된 영원한 불로 가라고 하며 같은 일을 하지 않았다고 하고(25:41~43), 그들도 언제 그러했느냐고 묻자 가장 낮은 사람 하나에게 하지 않은 일이 내게 하지 않은 일이라고 하십니다(25:44~45). 이 사람들은 영원한 벌로, 의인들은 영원한 생명으로 간다고 맺으십니다(25:46). 모든 민족이 누구인지, 가장 작은 형제가 누구인지(가난하고 아픈 모든 사람인지, 예수를 따르는 사람들인지), 이 심판에서 행한 일이 구원의 근거인지 열매인지, 영원한 벌과 불이 어떤 것인지는 교회마다 이해가 다릅니다. 본문은 두 무리가 모두 언제 그랬느냐고 되묻는다는 것을 적습니다. 이 말씀을 선행의 횟수를 세어 서로 견주거나 자신과 이웃을 양과 염소로 가르는 말로 쓰지 않습니다."
        ],
        "stay": "오늘 마음에 걸리는 한 사람을 떠올리며, 그 사람을 위해 하나님께 말씀드립니다.",
