        "read": "성경을 펴서 두 번 읽으며 음모와 향유를 부은 여인, 유다가 대제사장들에게 하는 일, 유월절 식사에서 예수께서 하시는 말씀과 떡과 잔, 감람산에서 하신 예고, 겟세마네에서의 기도와 제자들, 체포와 공회에서의 일, 마지막에 베드로가 뜰에서 하는 일을 차례대로 살펴보십시오. 길어서 26:17~30, 26:36~46, 26:69~75를 먼저 읽고 나머지는 훑어도 좋습니다.",
