            "t": "떠나다, 버려두다를 뜻하는 낱말입니다. 예수께서는 큰 소리로 하나님께 어찌하여 버리셨느냐고 외치십니다(27:46). 이 외침은 시편 22편의 첫머리와 같은 뜻의 말입니다. 마태는 이를 인용이라고 밝히지 않으며, 이 외침을 어떻게 이해할지는 교회마다 이해가 다릅니다."
