          "5장 1~4절은 몸에 병이 있는 사람과 몸에서 무언가 나오는 사람과 주검으로 정결하지 않게 된 사람을 진 밖으로 내보내라고 합니다. 까닭은 하나님이 그 진 가운데 거하시기 때문입니다(5:3). 이스라엘 자손은 그대로 했다고 적습니다(5:4). 이 장은 밖에 머무는 기간을 적지 않지만, 레위기 14장 2~3절과 15장은 정결하게 되어 돌아오는 길을 적어 두었습니다. 책을 시작하며 진을 세운 말씀(2장)이 그 가운데 계신 하나님을 중심으로 하는 것과 이어집니다.",
