          "5장 11~31절은 남편이 아내를 의심하는 경우를 다룹니다. 증인이 없고 마음에 의심이 생겼을 때 제사장 앞에 데려가 정해진 절차를 따르게 합니다(5:12~15; 5:24). 오늘의 독자에게는 읽기 어려운 대목입니다. 이 절차의 뜻과 이 규정을 오늘 어떻게 이해할지는 교회마다 이해가 다릅니다.",
