        "look": "25장 1~3절에서 이스라엘이 싯딤에서 한 일은 무엇입니까? 25장 6~13절에서 비느하스가 한 일과 하나님이 그에게 하신 말씀은 무엇입니까? 26장 63~65절은 이 계수에 든 사람들이 처음 계수와 어떻게 다르다고 적습니까? 27장 1~4절에서 딸들은 무엇을 청합니까? 27장 5~11절에서 하나님은 어떻게 답하십니까? 27장 15~17절에서 모세는 누구를 위해 무엇을 구합니까?",
