        "look": "31장 1~2절에서 하나님은 모세에게 무엇을 하라고 하십니까? 32장 1~6절에서 르우벤 자손과 갓 자손은 무엇을 청하고 모세는 무엇이라 답합니까? 33장 1~2절에서 모세는 하나님의 명령에 따라 무엇을 적습니까? 35장 11~12절에서 도피성은 누구를 위한 곳이고, 그 사람은 어떻게 됩니까? 35장 34절에서 하나님은 자신을 땅에 대해 어떻게 말씀하십니까? 36장 10~12절에서 슬로브핫의 딸들은 어떻게 합니까?",
        "ask": "내가 지나온 길을 하나하나 적어 둔다면 어느 자리에서 가장 오래 머물렀습니까? 그 자리에서 하나님이 어디 계셨다고 느꼈습니까, 혹은 느끼지 못했습니까?",
        "p": [
          "31장에서 하나님은 모세에게 미디안 사람들에게 원수를 갚으라고 하시고, 그 뒤에 모세가 자기 백성에게로 돌아가리라고 하십니다(31:2). 각 지파에서 천 명씩 만 이천 명이 나가고, 비느하스가 거룩한 기구와 나팔을 가지고 함께 갑니다(31:4~6). 미디안의 남자들은 죽고 발람도 칼에 죽습니다(31:7~8). 돌아온 지휘관들에게 모세는 크게 노하여 사로잡은 사람들 가운데 죽여야 할 사람들을 일러 주는데, 그 가운데 사내아이들도 든다고 본문이 적습니다(31:14~18). 이 싸움 이야기를 오늘 어떻게 읽을지는 교회마다 이해가 다릅니다. 이어서 싸움에 나갔던 사람들은 진 밖에서 이레 동안 머물며 씻고(31:19~24), 전리품은 둘로 나뉘어 제사장과 레위인의 몫이 따로 정해집니다(31:27~30). 지휘관들은 한 사람도 잃지 않았다고 말하며 금 예물을 하나님 앞에 가져옵니다(31:49~50).",
          "32장에서 르우벤과 갓 자손은 가축이 많아 요단 동쪽 땅을 달라고 청합니다(32:1~5). 모세는 형제들이 싸우러 가는데 너희는 여기 머물겠느냐고 묻고, 가데스바네아에서 정탐꾼들이 한 일을 떠올립니다(32:6~9). 그들이 가족을 위한 성읍을 짓고 무장하여 형제들 앞서 나가겠다고 하자 모세는 그 약속을 하나님 앞에서 지키라고 합니다(32:16~22). 모세는 요단 동쪽 땅을 르우벤과 갓과 므낫세 반 지파에게 줍니다(32:33).",
          "33장은 이집트에서 나와 걸어온 길의 구간들을 하나씩 적은 기록입니다. 본문은 모세가 하나님의 명령에 따라 그들이 떠난 곳을 기록했다고 적습니다(33:1~2). 요단을 건너면 그 땅의 주민을 몰아내고 우상을 부수라는 말씀도 이어집니다(33:50~52). 이 말씀을 오늘 어떻게 읽을지는 교회마다 이해가 다릅니다. 34장은 땅의 경계와 땅을 나눌 지도자들의 이름을 적습니다(34:1~29). 35장에서 레위인은 성읍들을 받고, 그 가운데 여섯 곳은 도피성이 됩니다(35:6). 알지 못하고 사람을 죽인 사람은 피 값을 갚으려는 사람을 피해 그곳으로 들어가고, 회중 앞에서 재판받을 때까지 보호받습니다(35:11~12). 대제사장이 죽을 때까지 그 성읍에 머물러야 하고(35:25), 사람을 죽였다는 증거는 증인 둘 이상의 말로만 세워집니다(35:30). 본문은 일부러 죽인 사람에게는 죽음의 벌을 정합니다(35:16~21; 35:31). 본문은 이 규정의 마지막에서 피가 땅을 더럽히며 하나님이 그 가운데 거하시는 땅을 더럽히지 말라고 합니다(35:33~34). 이 규정을 오늘의 형벌과 어떻게 이을지는 교회마다 이해가 다릅니다.",
          "36장에서 길르앗 지파의 가장들이 모세에게 와서 말합니다. 슬로브핫의 딸들이 다른 지파로 시집가면 그들의 기업이 그 지파에 더해져 우리 지파의 몫이 줄어든다는 것입니다(36:1~4). 모세는 하나님의 말씀대로 그 말이 옳다고 하며 딸들이 좋은 대로 시집가되 자기 지파 안의 친족에게 가라고 말합니다(36:5~6). 기업이 한 지파에서 다른 지파로 옮겨 가지 않게 하려는 것입니다(36:7~9). 딸들은 하나님이 모세에게 명하신 대로 사촌들에게 시집갑니다(36:10~12). 27장에서 이름을 청한 딸들의 이름이 책의 끝에서 다시 불립니다(36:11). 책의 마지막 절은 이 모든 말씀이 모압 평지에서 여리고 맞은편 요단 가에서 하나님이 모세를 통해 주신 계명과 규례라고 적습니다(36:13)."
        ],
        "stay": "지나온 길 가운데 한 자리를 떠올려 그곳에서 있었던 일을 하나님 앞에 있는 그대로 적어 봅니다. 하나님이 이스라엘 가운데 거하신다고 하신 말씀을 오늘 한 번 떠올립니다.",
